const FRAGMENT = "precision highp float;\nuniform vec2 uSize;\nuniform float uTime;\nuniform vec4 uArt;\nuniform float uSweep;\n\nfloat hash(vec2 p) {\n  vec3 a = fract(p.xyx * vec3(.1031, .11369, .13787));\n  a += dot(a, a.yzx + 19.19);\n  return fract((a.x + a.y) * a.z);\n}\nfloat noise(vec2 p) {\n  vec2 i = floor(p), f = fract(p);\n  f = f * f * (3. - 2. * f);\n  return mix(mix(hash(i), hash(i + vec2(1., 0.)), f.x),\n    mix(hash(i + vec2(0., 1.)), hash(i + vec2(1., 1.)), f.x), f.y);\n}\nfloat cloud(vec2 p) {\n  return .60 * noise(p) + .27 * noise(p * 2.13 + 7.) + .13 * noise(p * 4.27 - 11.);\n}\n// Recursive Bayer thresholds, locked to the low-resolution backing grid.\nfloat bayer2(vec2 i) {\n  i = mod(i, 2.);\n  return mod(i.x + i.y, 2.) * 2. + i.y;\n}\nfloat bayer8(vec2 i) {\n  return (16. * bayer2(i) + 4. * bayer2(floor(i / 2.)) + bayer2(floor(i / 4.)) + .5) / 64.;\n}\n// Front projection traced face by face from the approved silhouette.\nfloat edge(vec2 p, vec2 a, vec2 b) {\n  vec2 e = b - a, v = p - a;\n  return (e.x * v.y - e.y * v.x) / length(e);\n}\nfloat quad(vec2 p, vec2 a, vec2 b, vec2 c, vec2 d) {\n  vec4 s = vec4(edge(p,a,b),edge(p,b,c),edge(p,c,d),edge(p,d,a));\n  return max(min(min(s.x,s.y),min(s.z,s.w)), -max(max(s.x,s.y),max(s.z,s.w)));\n}\nfloat segment(vec2 p, vec2 a, vec2 b) {\n  vec2 e = b - a, v = p - a;\n  return length(v - e * clamp(dot(v,e)/dot(e,e),0.,1.));\n}\nvoid face(inout vec4 m, float d, float angle, float polish, float occlusion) {\n  if (d > m.w) m = vec4(angle, polish, occlusion, d);\n}\nvec4 steel(vec2 p, float phase, float dots) {\n  if (p.x < 163. || p.x > 593. || p.y < 15. || p.y > 750.) return vec4(0.);\n  vec4 m = vec4(0.,0.,0.,-1e4);\n  face(m, quad(p,vec2(321,21),vec2(373,31),vec2(585,185),vec2(535,179)), .95, 1.05, .11);\n  face(m, quad(p,vec2(321,21),vec2(535,179),vec2(463,253),vec2(321,145)), -.48, .76, .095);\n  face(m, quad(p,vec2(535,179),vec2(585,185),vec2(590,465),vec2(537,471)), 1.11, 1.07, .13);\n  face(m, quad(p,vec2(463,253),vec2(535,179),vec2(537,471),vec2(465,529)), -.82, .68, .077);\n  face(m, quad(p,vec2(465,529),vec2(537,471),vec2(590,465),vec2(507,529)), -2., .28, .02);\n  face(m, quad(p,vec2(367,185),vec2(445,242),vec2(447,389),vec2(370,385)), 2.6, .37, .04);\n  face(m, quad(p,vec2(170,311),vec2(367,185),vec2(367,292),vec2(211,392)), .43, .89, .09);\n  face(m, quad(p,vec2(211,392),vec2(367,292),vec2(370,385),vec2(260,438)), -2.7, .48, .04);\n  face(m, quad(p,vec2(170,311),vec2(211,392),vec2(260,438),vec2(166,551)), -.66, .69, .073);\n  face(m, quad(p,vec2(166,551),vec2(260,438),vec2(260,529),vec2(411,746)), -.66, .69, .073);\n  face(m, quad(p,vec2(166,551),vec2(260,529),vec2(472,685),vec2(411,746)), -.66, .69, .073);\n  face(m, quad(p,vec2(260,438),vec2(317,429),vec2(518,580),vec2(474,591)), .92, 1.05, .10);\n  face(m, quad(p,vec2(260,438),vec2(474,591),vec2(472,685),vec2(260,529)), -2.3, .43, .039);\n  face(m, quad(p,vec2(474,591),vec2(518,580),vec2(518,683),vec2(472,685)), 1.19, .97, .095);\n  face(m, quad(p,vec2(411,746),vec2(472,685),vec2(518,683),vec2(467,738)), -2.5, .25, .024);\n  if (m.w < -2.) return vec4(0.);\n  vec2 q = p / vec2(806.,804.);\n  // One soft pass over the bevels, then the steel settles back to its resting light.\n  float drive = mix(.14, 1.05, phase);\n  float path = q.y * .94 + q.x * .38 + .052 * sin(q.x * 7.);\n  float band = (path - drive) / .166;\n  float sweep = exp(-band * band) * smoothstep(0., .19, phase) * (1. - smoothstep(.76, 1., phase));\n  float facing = .57 + .43 * cos(m.x - .24);\n  float grain = .62 + .44 * noise(p * .39) + .27 * noise(p * vec2(.22,.54));\n  float pits = hash(floor(p * .9));\n  grain *= .77 + .42 * smoothstep(.06,.57,pits);\n  float bevel = exp(-max(m.w,0.) * .42) * (.28 + .36 * sweep) * m.y;\n  float value = m.z * grain + m.y * (.30 * sweep * facing * grain + .23 * bevel);\n  value = floor(value * 33. + dots) / 33.;\n  vec3 metal = vec3(.31,.56,.91) * value;\n  float weld = min(segment(p,vec2(369,302),vec2(370,387)), segment(p,vec2(370,387),vec2(279,439)));\n  metal += vec3(1.,.12,.035) * exp(-weld * .31) * (.21 + .27 * sweep);\n  return vec4(metal, .89 * smoothstep(-1., 4., m.w));\n}\nvoid main() {\n  vec2 p = gl_FragCoord.xy / uSize;\n  float t = uTime;\n  float drift = cloud(vec2(p.x * 5.5 - t * .26, p.y * 19. + .13 * sin(t * .32)));\n  float eddies = cloud(vec2(p.x * 8.3 + t * .16, p.y * 28. - t * .054));\n  float ground = (p.y - .134 - .025 * drift) * 13.5;\n  float high = (p.y - .314 - .04 * (eddies - .5)) * 10.;\n  float lower = exp(-ground * ground);\n  float upper = exp(-high * high);\n  float light = smoothstep(.19, .66, p.x) * (1. - smoothstep(.93, 1., p.x) * .42);\n  float density = (lower * smoothstep(.33, .73, drift) * .48\n    + upper * smoothstep(.36, .77, eddies) * .25) * light;\n  float dots = bayer8(floor(gl_FragCoord.xy));\n  float mist = floor(density * 26. + dots) / 26.;\n  vec2 art = (vec2(p.x,1. - p.y) - uArt.xy) / uArt.zw * vec2(806.,804.);\n  vec4 metal = steel(art, uSweep, dots);\n  vec3 fog = mix(vec3(.15,.26,.46), vec3(.41,.61,.88), drift);\n  float alpha = mist + metal.a * (1. - mist);\n  gl_FragColor = vec4((fog * mist + metal.rgb * metal.a * (1. - mist)) / max(alpha,.001), alpha);\n}\n"
const VERTEX = 'attribute vec2 aPos; void main() { gl_Position = vec4(aPos, 0.0, 1.0); }'
const FRAME_MS = 1000 / 24
const SWEEP_MS = 2800

function makeProgram(gl) {
  const shaders = []
  let program, buffer, okay = false
  try {
    for (const [type, source] of [[gl.VERTEX_SHADER, VERTEX], [gl.FRAGMENT_SHADER, FRAGMENT]]) {
      const shader = gl.createShader(type)
      if (!shader) return null
      shaders.push(shader)
      gl.shaderSource(shader, source)
      gl.compileShader(shader)
      if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) return null
    }
    program = gl.createProgram()
    if (!program) return null
    for (const shader of shaders) gl.attachShader(program, shader)
    gl.bindAttribLocation(program, 0, 'aPos')
    gl.linkProgram(program)
    if (!gl.getProgramParameter(program, gl.LINK_STATUS)) return null
    buffer = gl.createBuffer()
    if (!buffer) return null
    gl.useProgram(program)
    gl.bindBuffer(gl.ARRAY_BUFFER, buffer)
    gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW)
    gl.enableVertexAttribArray(0)
    gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0)
    okay = true
    return { program, buffer, size: gl.getUniformLocation(program, 'uSize'), time: gl.getUniformLocation(program, 'uTime'), art: gl.getUniformLocation(program, 'uArt'), sweep: gl.getUniformLocation(program, 'uSweep') }
  } finally {
    for (const shader of shaders) gl.deleteShader(shader)
    if (!okay) {
      if (program) gl.deleteProgram(program)
      if (buffer) gl.deleteBuffer(buffer)
    }
  }
}

function makeStage() {
  const stage = document.createElement('div')
  stage.dataset.cwmStage = ''
  stage.setAttribute('aria-hidden', 'true')
  const art = document.createElement('div')
  art.dataset.cwmMonument = ''
  const canvas = document.createElement('canvas')
  canvas.dataset.cwmHaze = ''
  stage.append(art, canvas)
  document.body.prepend(stage)
  document.documentElement.dataset.cwmMounted = ''
  let gl
  try {
    gl = canvas.getContext('webgl', { alpha: true, premultipliedAlpha: false, antialias: false,
      depth: false, stencil: false, powerPreference: 'low-power', failIfMajorPerformanceCaveat: false })
  } catch { /* No WebGL: keep the exact artwork and quiet background. */ }
  if (!gl) {
    canvas.remove()
    return () => stage.remove()
  }
  let gpu = makeProgram(gl)
  let raf = 0, last = null, elapsed = 0, deadline = 0, width = 0, height = 0
  let artFrame
  const motion = window.matchMedia('(prefers-reduced-motion: reduce)')
  let reduced = motion.matches
  let pendingUntil = 0, sweepStart = null
  const visible = () => width > 0 && height > 0 && !document.hidden && gpu
  function clearSweep() { pendingUntil = 0; sweepStart = null }
  function paint(time, sweep = 1) {
    gl.viewport(0, 0, canvas.width, canvas.height)
    gl.uniform2f(gpu.size, canvas.width, canvas.height)
    gl.uniform1f(gpu.time, time)
    gl.uniform1f(gpu.sweep, sweep)
    gl.uniform4fv(gpu.art, artFrame)
    gl.drawArrays(gl.TRIANGLES, 0, 3)
  }
  function stop() {
    cancelAnimationFrame(raf)
    raf = 0
    last = null
    deadline = 0
  }
  function tick(now) {
    raf = 0
    if (!visible() || reduced) return
    if (last !== null) elapsed += Math.min(100, now - last)
    last = now
    if (now >= deadline) {
      deadline = deadline && now - deadline < FRAME_MS ? deadline + FRAME_MS : now + FRAME_MS
      if (pendingUntil) {
        if (now < pendingUntil) sweepStart = now
        pendingUntil = 0
      }
      const progress = sweepStart === null ? 1 : Math.min(1, (now - sweepStart) / SWEEP_MS)
      if (progress === 1) sweepStart = null
      paint(elapsed / 1000 + 9, progress)
    }
    raf = requestAnimationFrame(tick)
  }
  function sync() {
    stop()
    if (!visible()) {
      if (sweepStart !== null || document.hidden || !gpu) clearSweep()
      return
    }
    if (reduced) paint(elapsed / 1000 + 9)
    else raf = requestAnimationFrame(tick)
  }
  function resize() {
    width = canvas.clientWidth
    height = canvas.clientHeight
    if (width && height) {
      const bounds = art.getBoundingClientRect(), frame = canvas.getBoundingClientRect()
      artFrame = [(bounds.left - frame.left) / width, (bounds.top - frame.top) / height, bounds.width / width, bounds.height / height]
      const scale = Math.max(3, width / 680, height / 420)
      canvas.width = Math.ceil(width / scale)
      canvas.height = Math.ceil(height / scale)
    }
    sync()
  }
  const observer = new ResizeObserver(resize)
  observer.observe(canvas)
  const changeMotion = event => { reduced = event.matches; if (reduced) clearSweep(); sync() }
  const lose = event => { event.preventDefault(); gpu = null; clearSweep(); stop() }
  const restore = () => { gpu = makeProgram(gl); resize() }
  // Desktop's explicit workspace New Chat pushes a fresh #/ history entry,
  // even from #/ itself. Back/forward, startup restores, and repaint are not new chats.
  const navigation = window.navigation
  const changeEntry = event => {
    clearSweep()
    if (event.navigationType !== 'push' || location.hash !== '#/' || reduced || document.hidden || !gpu) return
    // The workspace may still be swapping the outgoing transcript when the route lands.
    pendingUntil = performance.now() + 1000
  }
  canvas.addEventListener('webglcontextlost', lose)
  canvas.addEventListener('webglcontextrestored', restore)
  motion.addEventListener('change', changeMotion)
  document.addEventListener('visibilitychange', sync)
  navigation?.addEventListener('currententrychange', changeEntry)
  resize()
  return () => {
    stop()
    observer.disconnect()
    canvas.removeEventListener('webglcontextlost', lose)
    canvas.removeEventListener('webglcontextrestored', restore)
    motion.removeEventListener('change', changeMotion)
    document.removeEventListener('visibilitychange', sync)
    navigation?.removeEventListener('currententrychange', changeEntry)
    if (gpu) { gl.deleteBuffer(gpu.buffer); gl.deleteProgram(gpu.program) }
    gl.getExtension('WEBGL_lose_context')?.loseContext()
    stage.remove()
  }
}

const owns = name => name === ID || /^cyberwarmachine-accent-[0-9a-f]{6}$/i.test(name)
function observeTheme() {
  const root = document.documentElement
  let disposeStage
  const unmount = () => {
    disposeStage?.()
    disposeStage = undefined
    delete root.dataset.cwmMounted
  }
  const sync = () => {
    if (owns(root.dataset.hermesTheme ?? '')) disposeStage ??= makeStage()
    else if (disposeStage) unmount()
  }
  const observer = new MutationObserver(sync)
  observer.observe(root, { attributes: true, attributeFilter: ['data-hermes-theme'] })
  sync()
  return () => { observer.disconnect(); if (disposeStage) unmount() }
}

export default {
  id: ID, name: 'CyberWarMachine', defaultEnabled: false,
  register(ctx) {
    ctx.register({ id: ID, area: THEMES_AREA, data: theme })
    ctx.onDispose(observeTheme())
  }
}
